SELECT b.board_id, b.member_id, b.category, b.title, b.content, b.count, b.like_count, b.create_at, DATE_FORMAT(b.create_at, '%Y-%m-%d %H:%i') AS create_at_str, b.update_at, m.nickname FROM board b LEFT JOIN member m ON b.member_id = m.member_id
AND b.category = #{category}
AND (b.title LIKE CONCAT('%', #{keyword}, '%') OR b.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY b.create_at DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM board
AND category = #{category}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))

